import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { getProduits } from "../services/serviceProduits";
import { usePanier } from "../hooks/usePanier";

const categories = [
  { icon: "💻", nom: "Informatique", slug: "electronics" },
  { icon: "💍", nom: "Bijoux",       slug: "jewelery" },
  { icon: "👔", nom: "Homme",        slug: "men's clothing" },
  { icon: "👗", nom: "Femme",        slug: "women's clothing" },
];

const couleur = "#3B5BDB";

export default function Accueil() {
  const [produits, setProduits] = useState([]);
  const [chargement, setChargement] = useState(true);
  const { ajouterAuPanier } = usePanier();

  useEffect(() => {
    getProduits()
      .then((data) => setProduits(data.slice(0, 8)))
      .finally(() => setChargement(false));
  }, []);

  return (
    <div style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>

      {/* ── HERO BANNER ── */}
      <div style={{
        background: `linear-gradient(135deg, ${couleur} 0%, #4C6EF5 60%, #748FFC 100%)`,
        borderRadius: "16px",
        padding: "40px 48px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        marginBottom: "32px",
        overflow: "hidden",
        position: "relative",
      }}>
        {/* Cercles décoratifs */}
        <div style={{ position: "absolute", width: "200px", height: "200px", background: "rgba(255,255,255,0.06)", borderRadius: "50%", top: "-60px", right: "200px" }} />
        <div style={{ position: "absolute", width: "140px", height: "140px", background: "rgba(255,255,255,0.06)", borderRadius: "50%", bottom: "-40px", right: "80px" }} />

        <div style={{ zIndex: 1 }}>
          <p style={{ color: "rgba(255,255,255,0.75)", fontSize: "13px", marginBottom: "8px", fontWeight: 500, letterSpacing: "1px", textTransform: "uppercase" }}>
            Bienvenue sur E-Store
          </p>
          <h1 style={{ color: "white", fontSize: "32px", fontWeight: 700, lineHeight: 1.25, marginBottom: "12px", maxWidth: "420px" }}>
            Des milliers de produits au meilleur prix
          </h1>
          <p style={{ color: "rgba(255,255,255,0.8)", fontSize: "14px", marginBottom: "24px", maxWidth: "380px" }}>
            Électronique, mode, bijoux et plus encore — livraison gratuite  apartire dès 500 DH.
          </p>
          <div style={{ display: "flex", gap: "12px" }}>
            <Link to="/catalogue">
              <button style={{ background: "white", color: couleur, fontWeight: 700, fontSize: "14px", padding: "11px 24px", borderRadius: "8px", border: "none", cursor: "pointer" }}>
                Voir le catalogue →
              </button>
            </Link>
            <Link to="/inscription">
              <button style={{ background: "rgba(255,255,255,0.15)", color: "white", fontWeight: 600, fontSize: "14px", padding: "11px 24px", borderRadius: "8px", border: "1px solid rgba(255,255,255,0.3)", cursor: "pointer" }}>
                S'inscrire
              </button>
            </Link>
          </div>
        </div>

        {/* Illustrations produits côté droit */}
        <div style={{ display: "flex", gap: "12px", zIndex: 1 }}>
          {["💻", "🎧", "⌚"].map((icon, i) => (
            <div key={i} style={{
              width: "80px", height: "80px",
              background: "rgba(255,255,255,0.15)",
              backdropFilter: "blur(8px)",
              borderRadius: "16px",
              display: "flex", alignItems: "center", justifyContent: "center",
              fontSize: "36px",
              border: "1px solid rgba(255,255,255,0.25)",
              transform: i === 1 ? "translateY(-10px)" : "none",
            }}>
              {icon}
            </div>
          ))}
        </div>
      </div>

      {/* ── STATS RAPIDES ── */}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: "14px", marginBottom: "32px" }}>
        {[
          { valeur: "500+", label: "Produits disponibles", icon: "📦", bg: "#EEF2FF", color: couleur },
          { valeur: "4",    label: "Catégories",            icon: "🗂️",  bg: "#E6FCF5", color: "#0CA678" },
          { valeur: "24h",  label: "Livraison rapide",      icon: "🚚",  bg: "#FFF9DB", color: "#F08C00" },
          { valeur: "100%", label: "Paiement sécurisé",     icon: "🔒",  bg: "#FFF5F5", color: "#E03131" },
        ].map((s, i) => (
          <div key={i} style={{ background: s.bg, borderRadius: "12px", padding: "18px 20px", display: "flex", alignItems: "center", gap: "14px" }}>
            <span style={{ fontSize: "28px" }}>{s.icon}</span>
            <div>
              <div style={{ fontSize: "20px", fontWeight: 700, color: s.color }}>{s.valeur}</div>
              <div style={{ fontSize: "12px", color: "#868E96" }}>{s.label}</div>
            </div>
          </div>
        ))}
      </div>

      {/* ── CATÉGORIES ── */}
      <div style={{ marginBottom: "32px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px" }}>
          <h2 style={{ fontSize: "17px", fontWeight: 700, color: "#212529" }}>Catégories populaires</h2>
          <Link to="/catalogue" style={{ fontSize: "13px", color: couleur, fontWeight: 600 }}>Voir tout →</Link>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: "12px" }}>
          {categories.map((cat) => (
            <Link key={cat.slug} to={`/catalogue?categorie=${cat.slug}`}>
              <div style={{
                background: "white",
                border: `1.5px solid #e9ecef`,
                borderRadius: "12px",
                padding: "20px",
                textAlign: "center",
                cursor: "pointer",
                transition: "all 0.2s",
              }}
                onMouseEnter={e => { e.currentTarget.style.borderColor = couleur; e.currentTarget.style.background = "#EEF2FF"; }}
                onMouseLeave={e => { e.currentTarget.style.borderColor = "#e9ecef"; e.currentTarget.style.background = "white"; }}
              >
                <div style={{ fontSize: "36px", marginBottom: "10px" }}>{cat.icon}</div>
                <div style={{ fontSize: "14px", fontWeight: 600, color: "#212529" }}>{cat.nom}</div>
              </div>
            </Link>
          ))}
        </div>
      </div>

      {/* ── PRODUITS EN VEDETTE ── */}
      <div style={{ marginBottom: "32px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px" }}>
          <h2 style={{ fontSize: "17px", fontWeight: 700, color: "#212529" }}>Produits en vedette</h2>
          <Link to="/catalogue" style={{ fontSize: "13px", color: couleur, fontWeight: 600 }}>Voir tout →</Link>
        </div>

        {chargement ? (
          <div style={{ textAlign: "center", padding: "40px", color: "#868E96" }}>Chargement...</div>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: "14px" }}>
            {produits.map((p) => (
              <div key={p.id} style={{
                background: "white",
                border: "0.5px solid #e9ecef",
                borderRadius: "12px",
                padding: "16px",
                display: "flex",
                flexDirection: "column",
                gap: "10px",
                transition: "border-color 0.2s",
              }}
                onMouseEnter={e => e.currentTarget.style.borderColor = couleur}
                onMouseLeave={e => e.currentTarget.style.borderColor = "#e9ecef"}
              >
                {/* Image produit */}
                <Link to={`/produit/${p.id}`}>
                  <div style={{ background: "#f8f9fa", borderRadius: "8px", height: "130px", display: "flex", alignItems: "center", justifyContent: "center", overflow: "hidden" }}>
                    <img src={p.image} alt={p.title} style={{ maxHeight: "110px", maxWidth: "100%", objectFit: "contain" }} />
                  </div>
                </Link>

                {/* Catégorie badge */}
                <span style={{ fontSize: "11px", background: "#EEF2FF", color: couleur, padding: "2px 8px", borderRadius: "20px", fontWeight: 600, width: "fit-content", textTransform: "capitalize" }}>
                  {p.category}
                </span>

                {/* Nom */}
                <Link to={`/produit/${p.id}`}>
                  <p style={{ fontSize: "13px", fontWeight: 500, color: "#212529", lineHeight: 1.4 }}>
                    {p.title.length > 45 ? p.title.slice(0, 45) + "..." : p.title}
                  </p>
                </Link>

                {/* Étoiles */}
                <div style={{ display: "flex", alignItems: "center", gap: "4px" }}>
                  <span style={{ color: "#F59F00", fontSize: "12px" }}>{"★".repeat(Math.round(p.rating?.rate || 0))}</span>
                  <span style={{ fontSize: "11px", color: "#adb5bd" }}>({p.rating?.count})</span>
                </div>

                {/* Prix + bouton */}
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: "auto" }}>
                  <span style={{ fontSize: "15px", fontWeight: 700, color: "#212529" }}>{p.price} €</span>
                  <button
                    onClick={() => ajouterAuPanier(p)}
                    style={{ background: couleur, color: "white", border: "none", borderRadius: "8px", padding: "7px 14px", fontSize: "12px", fontWeight: 600, cursor: "pointer" }}
                  >
                    + Panier
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* ── BANNIERE BAS ── */}
      <div style={{
        background: `linear-gradient(135deg, #212529, #343A40)`,
        borderRadius: "14px",
        padding: "32px 40px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
      }}>
        <div>
          <h3 style={{ color: "white", fontSize: "20px", fontWeight: 700, marginBottom: "8px" }}>
            Livraison gratuite dès 500 DH 🚚
          </h3>
          <p style={{ color: "rgba(255,255,255,0.65)", fontSize: "13px" }}>
            Commandez maintenant et recevez vos articles en 24h
          </p>
        </div>
        <Link to="/catalogue">
          <button style={{ background: couleur, color: "white", fontWeight: 700, fontSize: "14px", padding: "12px 28px", borderRadius: "8px", border: "none", cursor: "pointer" }}>
            Commander maintenant →
          </button>
        </Link>
      </div>

    </div>
  );
}
